import { test, expect } from '@playwright/test';

test.describe('Search Results Sorting', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/search');
  });

  test('should sort search results by relevance', async ({ page }) => {
    await page.getByRole('button', { name: /sort by/i }).click();
    await page.getByText('Relevance').click();

    const firstResult = await page.getByRole('article').nth(0).innerText();
    const secondResult = await page.getByRole('article').nth(1).innerText();

    expect(firstResult).toBeGreaterThan(secondResult); // Assuming relevance can be compared this way
  });

  test('should sort search results by price', async ({ page }) => {
    await page.getByRole('button', { name: /sort by/i }).click();
    await page.getByText('Price').click();

    const firstPrice = await page.getByRole('article').nth(0).getByLabel('Price').innerText();
    const secondPrice = await page.getByRole('article').nth(1).getByLabel('Price').innerText();

    expect(parseFloat(firstPrice.replace('$', ''))).toBeLessThan(parseFloat(secondPrice.replace('$', '')));
  });
});
